typedef unsigned int u_int;

struct nglMesh;
struct nglMaterial
{
	u_int Flags;
	char padding[260];
};
struct WaveMeshHandle
{
	nglMesh *baseid[2];
};
struct WavetexDebugStruct
{
	char padding0[60];
	int ScissorWaveMesh;
	char padding1[36];
	int UseLights;
};

extern u_int numwavemeshes;
extern WaveMeshHandle wavemeshes[6];
extern nglMaterial WaveTexLMat[][5];
extern int wavetex_currentmat;
extern WavetexDebugStruct WavetexDebug;
extern nglMesh *nglScratch;

void WAVETEX_InitMaterial( nglMaterial &, int, int, int );
void KSNGL_CreateScratchMesh( int, nglMaterial *, bool, bool = false );
void nglSetMeshFlags( u_int );

enum
{
	WAVETEX_PASSFULL,
	WAVETEX_TEXLITE = 0,
	NGLMAT_LIGHT = 0x00100000,
	NGLMESH_PERFECT_TRICLIP = 0x00000001,
	NGLMESH_LIGHTCAT_1 = 0x01000000,
	NGLMESH_LIGHTCAT_8 = 0x80000000
};

#define assert(condition) ((void)0)
#define WAVETEX_NUMBUFFER 2

u_int WAVETEX_InitWaveMesh( u_int nvert, int mattype, void (*fillinfunc)(void) )
{
	u_int rv=numwavemeshes++;
	assert(numwavemeshes<=6);
	WaveMeshHandle *wmh=&wavemeshes[rv];
		WAVETEX_InitMaterial( WaveTexLMat[wavetex_currentmat][mattype], WAVETEX_TEXLITE, WAVETEX_PASSFULL, mattype );
		WaveTexLMat[wavetex_currentmat][mattype].Flags |= NGLMAT_LIGHT;
	u_int MeshFlags = 0;
	MeshFlags |= NGLMESH_LIGHTCAT_8;
	if (WavetexDebug.UseLights)
	{
		MeshFlags |= NGLMESH_LIGHTCAT_1;
	}
	if (WavetexDebug.ScissorWaveMesh)
	{
		MeshFlags |= NGLMESH_PERFECT_TRICLIP;
	}

	for (u_int i = 0; i < WAVETEX_NUMBUFFER; ++i)
	{
  		KSNGL_CreateScratchMesh( nvert, &WaveTexLMat[wavetex_currentmat][mattype], true );
  		wmh->baseid[i] = nglScratch;
		nglSetMeshFlags( MeshFlags );
	}

  return rv;
}
